// Style represents text styling options
type Style struct {
	Hide      bool
	Bold      bool
	Faint     bool
	Italic    bool
	Underline bool
	BlinkSlow bool
	BlinkRapid bool
	Inverse   bool
	Conceal   bool
	CrossOut  bool
	Frame     bool
