	Background string
}

// Config holds the richstyle configuration
type Config struct {
	LabelType         string // "long", "short", "none"
	BuildStyle        Style
	StartStyle        Style
	PassStyle         Style
	FailStyle         Style
	SkipStyle         Style
	FileStyle         Style
	LineStyle         Style
	PassPackageStyle  Style
	FailPackageStyle  Style
	CoverThreshold    float64
	CoveredStyle      Style
	UncoveredStyle    Style
	Removals          []string
	LeaveTestPrefix   bool
}

// Default config
func defaultConfig() Config {
	return Config{
		LabelType: "long",
		BuildStyle: Style{
			Bold:       true,
			Foreground: "yellow",
		},
		StartStyle: Style{
			Foreground: "lightBlack",
		},
		PassStyle: Style{
			Foreground: "green",
		},
		FailStyle: Style{
			Bold:       true,
			Foreground: "red",
		},
		SkipStyle: Style{
			Foreground: "lightBlack",
		},
		PassPackageStyle: Style{
			Foreground: "green",
			Hide:       true,
		},
		FailPackageStyle: Style{
			Bold:       true,
			Foreground: "red",
			Hide:       true,
		},
