		fg := colorCode(style.Foreground, false)
		if fg != "" {
			codes = append(codes, fg)
		}
	}

	// Attributes
	if style.Bold {
		codes = append(codes, "\033[1m")
	}
	if style.Faint {
		codes = append(codes, "\033[2m")
	}
	if style.Italic {
		codes = append(codes, "\033[3m")
	}
	if style.Underline {
		codes = append(codes, "\033[4m")
	}
	if style.BlinkSlow {
		codes = append(codes, "\033[5m")
	}
	if style.BlinkRapid {
		codes = append(codes, "\033[6m")
	}
	if style.Inverse {
		codes = append(codes, "\033[7m")
	}
	if style.Conceal {
		codes = append(codes, "\033[8m")
	}
	if style.CrossOut {
		codes = append(codes, "\033[9m")
	}
	if style.Frame {
		codes = append(codes, "\033[51m")
	}
	if style.Encircle {
		codes = append(codes, "\033[52m")
	}
	if style.Overline {
		codes = append(codes, "\033[53m")
	}

	return strings.Join(codes, "")
}

const ansiReset = "\033[0m"

// colorCode returns the ANSI escape sequence for a color
func colorCode(color string, bg bool) string {
	offset := 30
	if bg {
		offset = 40
	}

	switch strings.ToLower(color) {
	case "black":
		return fmt.Sprintf("\033[%dm", offset+0)
	case "red":
		return fmt.Sprintf("\033[%dm", offset+1)
	case "green":
		return fmt.Sprintf("\033[%dm", offset+2)
	case "yellow":
		return fmt.Sprintf("\033[%dm", offset+3)
	case "blue":
		return fmt.Sprintf("\033[%dm", offset+4)
	case "magenta":
		return fmt.Sprintf("\033[%dm", offset+5)
	case "cyan":
		return fmt.Sprintf("\033[%dm", offset+6)
	case "white":
		return fmt.Sprintf("\033[%dm", offset+7)
	case "lightblack":
		return fmt.Sprintf("\033[%dm", offset+60)
	case "lightred":
		return fmt.Sprintf("\033[%dm", offset+61)
	case "lightgreen":
		return fmt.Sprintf("\033[%dm", offset+62)
	case "lightyellow":
		return fmt.Sprintf("\033[%dm", offset+63)
	case "lightblue":
		return fmt.Sprintf("\033[%dm", offset+64)
	case "lightmagenta":
		return fmt.Sprintf("\033[%dm", offset+65)
	case "lightcyan":
		return fmt.Sprintf("\033[%dm", offset+66)
	case "lightwhite":
		return fmt.Sprintf("\033[%dm", offset+67)
	}

	// Try hex #rrggbb
	if strings.HasPrefix(color, "#") && len(color) == 7 {
		r, err1 := strconv.ParseInt(color[1:3], 16, 32)
		g, err2 := strconv.ParseInt(color[3:5], 16, 32)
		b, err3 := strconv.ParseInt(color[5:7], 16, 32)
		if err1 == nil && err2 == nil && err3 == nil {
			if bg {
				return fmt.Sprintf("\033[48;2;%d;%d;%dm", r, g, b)
			}
			return fmt.Sprintf("\033[38;2;%d;%d;%dm", r, g, b)
		}
	}

	// Try rgb(r,g,b)
	if strings.HasPrefix(strings.ToLower(color), "rgb(") && strings.HasSuffix(color, ")") {
		inner := color[4 : len(color)-1]
		parts := strings.Split(inner, ",")
		if len(parts) == 3 {
			r, err1 := strconv.ParseInt(strings.TrimSpace(parts[0]), 10, 32)
			g, err2 := strconv.ParseInt(strings.TrimSpace(parts[1]), 10, 32)
			b, err3 := strconv.ParseInt(strings.TrimSpace(parts[2]), 10, 32)
			if err1 == nil && err2 == nil && err3 == nil {
				if bg {
					return fmt.Sprintf("\033[48;2;%d;%d;%dm", r, g, b)
				}
				return fmt.Sprintf("\033[38;2;%d;%d;%dm", r, g, b)
			}
		}
	}

	return ""
}

// Label types
func (c *Config) label(kind string) string {
	switch c.LabelType {
	case "short":
		switch kind {
		case "build":
			return "!! "
		case "start":
			return ">  "
		case "pass":
			return "o  "
		case "fail":
			return "x  "
		case "skip":
			return "-  "
		case "cover":
			return "%  "
		case "cont":
			return "   "
		}
	case "none":
		return ""
	default: // "long"
		switch kind {
		case "build":
			return "BUILD| "
		case "start":
			return "START| "
		case "pass":
			return "PASS | "
		case "fail":
			return "FAIL | "
		case "skip":
			return "SKIP | "
		case "cover":
			return "COVER| "
		case "cont":
			return "     | "
		}
	}
	return ""
}

// Continuation label (for unrecognized lines)
func (c *Config) contLabel() string {
	return c.label("cont")
}

// Regexes for parsing
var (
	reRun      = regexp.MustCompile(`^=== RUN   (Test.*)$`)
	rePass     = regexp.MustCompile(`^--- PASS: (Test\S*)\s*(.*)$`)
	reFail     = regexp.MustCompile(`^--- FAIL: (Test\S*)\s*(.*)$`)
	reSkip     = regexp.MustCompile(`^--- SKIP: (Test\S*)\s*(.*)$`)
	reBuild    = regexp.MustCompile(`^# (.+)$`)
	reCoverage = regexp.MustCompile(`^coverage: (\d+\.?\d*)% of statements$`)
	reOkPkg    = regexp.MustCompile(`^ok  \t([^\t]+)\t([^\t]+)(?:\t(coverage: .+))?$`)
	reFailPkg  = regexp.MustCompile(`^FAIL\t(.*)$`)
	reSkipPkg  = regexp.MustCompile(`^\?   \t(.*)$`)
	reFileRef  = regexp.MustCompile(`^(\s*)(\S+\.go(?::\d+(?::\d+)?)?)(:.*)?$`)
	reFileRef2 = regexp.MustCompile(`^(\s*)(\S+\.go)(:\d+(?::\d+)?)(.*)$`)
)

// applyRemovals applies the removal regexps to a string
func (c *Config) applyRemovals(s string) string {
	for _, pattern := range c.Removals {
		re, err := regexp.Compile(pattern)
		if err == nil {
			s = re.ReplaceAllString(s, "")
		}
	}
	return s
}

// formatTestName strips "Test" prefix if leaveTestPrefix is false
func (c *Config) formatTestName(name string) string {
	if c.LeaveTestPrefix {
		return name
	}
	if strings.HasPrefix(name, "Test") {
		return name[4:]
	}
	return name
}

// indentForTest returns the indentation string based on subtest depth
func indentForTest(name string) string {
	depth := strings.Count(name, "/")
	return strings.Repeat(" ", depth*2)
}

// coverBar generates a coverage bar like "[####______]"
func coverBar(coverage float64) string {
	filled := int(math.Floor(coverage / 10))
	if filled > 10 {
		filled = 10
	}
	bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
	return "[" + bar + "]"
}

// styled applies a style to text (with reset at end)
func styled(style Style, text string) string {
	code := ansiCode(style)
	if code == "" {
		return text
	}
	return code + text + ansiReset
}

// isFileRef checks if a line is a file reference line and returns components
func isFileRef(line string) (indent, file, linecol, message string, ok bool) {
	// Pattern: optional_spaces + filename.go + :line[:col] + : message
	// Or just: optional_spaces + filename.go + :line[:col]
	m := reFileRef2.FindStringSubmatch(line)
	if m == nil {
		return "", "", "", "", false
	}
	return m[1], m[2], m[3], m[4], true
}

// Processor handles the test output filtering
type Processor struct {
	config    Config
	useColor  bool
	inBuild   bool
	buildStyle Style
}

func (p *Processor) process(r io.Reader, w io.Writer) {
	if !p.useColor {
		// Pass through as-is
		io.Copy(w, r)
		fmt.Fprintln(w)
		fmt.Fprintln(w)
		return
	}

	scanner := bufio.NewScanner(r)
	c := &p.config

	for scanner.Scan() {
		line := scanner.Text()

		// Apply removals
		processedLine := c.applyRemovals(line)

		// Try to match line patterns
		if m := reRun.FindStringSubmatch(line); m != nil {
			// START line
			p.inBuild = false
			testName := m[1]
			indent := indentForTest(testName)
			displayName := c.formatTestName(testName)
			label := c.label("start")
			fmt.Fprintf(w, "%s%s%s%s\n",
				ansiCode(c.StartStyle),
				label,
				indent+displayName,
				ansiReset)
			continue
		}

		if m := rePass.FindStringSubmatch(line); m != nil {
			// PASS line
			p.inBuild = false
			if c.PassStyle.Hide {
				continue
			}
			testName := m[1]
			rest := m[2]
			indent := indentForTest(testName)
			displayName := c.formatTestName(testName)
			label := c.label("pass")
			displayName = c.applyRemovals(displayName)
			rest = c.applyRemovals(rest)
			content := indent + displayName
			if rest != "" {
				content += " " + rest
			}
			fmt.Fprintf(w, "%s%s%s%s\n",
				ansiCode(c.PassStyle),
				label,
				content,
				ansiReset)
			continue
		}

		if m := reFail.FindStringSubmatch(line); m != nil {
			// FAIL line
			p.inBuild = false
			if c.FailStyle.Hide {
				continue
			}
			testName := m[1]
			rest := m[2]
			indent := indentForTest(testName)
			displayName := c.formatTestName(testName)
			label := c.label("fail")
			displayName = c.applyRemovals(displayName)
			rest = c.applyRemovals(rest)
			content := indent + displayName
			if rest != "" {
				content += " " + rest
			}
			fmt.Fprintf(w, "%s%s%s%s\n",
				ansiCode(c.FailStyle),
				label,
				content,
				ansiReset)
			continue
		}

		if m := reSkip.FindStringSubmatch(line); m != nil {
			// SKIP line
			p.inBuild = false
			if c.SkipStyle.Hide {
				continue
			}
			testName := m[1]
			rest := m[2]
			indent := indentForTest(testName)
			displayName := c.formatTestName(testName)
			label := c.label("skip")
			displayName = c.applyRemovals(displayName)
			rest = c.applyRemovals(rest)
			content := indent + displayName
			if rest != "" {
				content += " " + rest
			}
			fmt.Fprintf(w, "%s%s%s%s\n",
				ansiCode(c.SkipStyle),
				label,
				content,
				ansiReset)
			continue
		}

		if m := reBuild.FindStringSubmatch(line); m != nil {
			// BUILD line (start)
			p.inBuild = true
			p.buildStyle = c.BuildStyle
			if c.BuildStyle.Hide {
				p.inBuild = false
				continue
			}
			pkgName := m[1]
			label := c.label("build")
			code := ansiCode(c.BuildStyle)
			fmt.Fprintf(w, "%s%s%s\n%s", code, label, pkgName, ansiReset)
			continue
		}

		if m := reCoverage.FindStringSubmatch(line); m != nil {
			// COVER line (standalone)
			p.inBuild = false
			covStr := m[1]
			cov, err := strconv.ParseFloat(covStr, 64)
			var coverStyle Style
			if err == nil && cov >= c.CoverThreshold {
				coverStyle = c.CoveredStyle
			} else {
				coverStyle = c.UncoveredStyle
			}
			if coverStyle.Hide {
				continue
			}
			bar := coverBar(cov)
			label := c.label("cover")
			fmt.Fprintf(w, "%s%s%s%% %s%s\n",
				ansiCode(coverStyle),
				label,
				covStr,
				bar,
				ansiReset)
			continue
		}

		if m := reOkPkg.FindStringSubmatch(line); m != nil {
			// Pass package line (ok)
			p.inBuild = false
			pkg := m[1]
			coverage := m[3]
			label := c.label("pass")
			content := pkg + " "
			if coverage != "" {
				content = pkg + " " + coverage
			}
			fmt.Fprintf(w, "%s%s%s%s\n",
				ansiCode(c.PassPackageStyle),
				label,
				content,
				ansiReset)
			continue
		}

		if line == "PASS" {
			// Standalone PASS (package result)
			p.inBuild = false
			if c.PassPackageStyle.Hide {
				continue
			}
			fmt.Fprintf(w, "%sPASS%s\n",
				ansiCode(c.PassPackageStyle),
				ansiReset)
			continue
		}

		if m := reFailPkg.FindStringSubmatch(line); m != nil {
			// FAIL package line
			p.inBuild = false
			rest := m[1]
			label := c.label("fail")
			if rest == "" {
				// Standalone FAIL
				if c.FailPackageStyle.Hide {
					continue
				}
				fmt.Fprintf(w, "%sFAIL%s\n",
					ansiCode(c.FailPackageStyle),
					ansiReset)
			} else {
				// FAIL\tpkg\ttime
				fmt.Fprintf(w, "%s%s\t%s%s\n",
					ansiCode(c.FailPackageStyle),
					label,
					rest,
					ansiReset)
			}
			continue
		}

		if m := reSkipPkg.FindStringSubmatch(line); m != nil {
			// Skip package line (? pkg [no test files])
			p.inBuild = false
			rest := m[1]
			label := c.label("skip")
			// rest is "pkg\t[no test files]"
			// We need to extract pkg from rest
			parts := strings.SplitN(rest, "\t", 2)
			pkg := parts[0]
			extra := ""
			if len(parts) > 1 {
				extra = "\t" + parts[1]
			}
			fmt.Fprintf(w, "%s%s%s%s%s\n",
				ansiCode(c.SkipStyle),
				label,
				pkg,
				extra,
				ansiReset)
			continue
		}

		// Unknown/continuation line
		if p.inBuild {
			// Build continuation line
			if c.BuildStyle.Hide {
				continue
			}
			// Process as file reference
			processedLine = c.applyRemovals(line)
			p.printFileLine(processedLine, c.BuildStyle, w)
			continue
		}

		// Regular continuation line
		contLabel := c.contLabel()
		processedLine = c.applyRemovals(line)
		// Check if it's the continuation of a fail/skip context
		// Just output with continuation label (no style)
		fmt.Fprintf(w, "%s%s\n", contLabel, processedLine)
	}
}

func (p *Processor) printFileLine(line string, style Style, w io.Writer) {
	indent, file, linecol, message, ok := isFileRef(line)
	code := ansiCode(style)
	fileCode := ansiCode(p.config.FileStyle)
	lineCode := ansiCode(p.config.LineStyle)
	contLabel := p.config.label("cont")
	if ok && file != "" && linecol != "" {
		// file reference line
		fmt.Fprintf(w, "%s%s%s%s%s%s%s%s%s%s\n",
			code,
			contLabel,
			indent,
			fileCode, file, ansiReset,
			lineCode, linecol, ansiReset,
			code+message+ansiReset)
	} else {
		fmt.Fprintf(w, "%s%s%s%s\n", code, contLabel, line, ansiReset)
	}
}

func isColorEnabled() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	// Check if stdout is a TTY
	if _, err := syscall.IoctlRetWinsize(int(os.Stdout.Fd()), syscall.TIOCGWINSZ); err == nil {
		return true
	}
	return false
}

func runTestFilter(r io.Reader, w io.Writer) {
	config := loadConfig()
	useColor := isColorEnabled()

	proc := &Processor{
		config:   config,
		useColor: useColor,
	}
	proc.process(r, w)
}

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		// No subcommand - run "go" with no args
		cmd := exec.Command("go")
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		return
	}

	if args[0] == "testfilter" {
		runTestFilter(os.Stdin, os.Stdout)
		return
	}

	if args[0] == "test" {
		// Run "go test" and pipe through testfilter
		goArgs := append([]string{"test"}, args[1:]...)
		cmd := exec.Command("go", goArgs...)

		useColor := isColorEnabled()

		if useColor || os.Getenv("RICHGO_FORCE_COLOR") == "1" {
			pr, pw, err := os.Pipe()
			if err != nil {
				cmd.Stdout = os.Stdout
				cmd.Stderr = os.Stderr
				cmd.Stdin = os.Stdin
				cmd.Run()
				return
			}
			cmd.Stdout = pw
			cmd.Stderr = pw
			cmd.Stdin = os.Stdin

			done := make(chan struct{})
			go func() {
				defer close(done)
				runTestFilter(pr, os.Stdout)
			}()

			cmd.Run()
			pw.Close()
			<-done
		} else {
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			cmd.Stdin = os.Stdin
			cmd.Run()
		}
		return
	}

	// Pass through to "go"
	cmd := exec.Command("go", args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}
GOEOF

