package main

import (
	"bufio"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// loadConfig loads the richstyle configuration from files
func loadConfig() Config {
	config := defaultConfig()

	paths := configPaths()
	for _, p := range paths {
		if data, err := os.ReadFile(p); err == nil {
			parseConfig(data, &config)
			break
		}
	}

	return config
}

// configPaths returns the list of config file paths to check in order
func configPaths() []string {
	var paths []string

	richgoLocal := os.Getenv("RICHGO_LOCAL") == "1"

	cwd, _ := os.Getwd()
	if cwd != "" {
		paths = append(paths,
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
		)
	}

	if richgoLocal {
		return paths
	}

	gopath := os.Getenv("GOPATH")
	if gopath != "" {
		paths = append(paths,
			filepath.Join(gopath, ".richstyle"),
			filepath.Join(gopath, ".richstyle.yaml"),
			filepath.Join(gopath, ".richstyle.yml"),
		)
	}

	goroot := os.Getenv("GOROOT")
	if goroot == "" {
		// Try to find GOROOT
		goroot = defaultGoRoot()
	}
	if goroot != "" {
		paths = append(paths,
			filepath.Join(goroot, ".richstyle"),
			filepath.Join(goroot, ".richstyle.yaml"),
			filepath.Join(goroot, ".richstyle.yml"),
		)
	}

	home, _ := os.UserHomeDir()
	if home != "" {
		paths = append(paths,
			filepath.Join(home, ".richstyle"),
			filepath.Join(home, ".richstyle.yaml"),
			filepath.Join(home, ".richstyle.yml"),
		)
	}

	return paths
}

func defaultGoRoot() string {
	// Try to get GOROOT from go env
	return ""
}

// parseConfig parses a YAML config file and updates the config
func parseConfig(data []byte, config *Config) {
	lines := strings.Split(string(data), "\n")

	// Simple YAML parser for the richstyle format
	// We handle:
	// - top-level key: value
	// - style blocks:
	//   styleKey:
	//     subkey: value
	// - list:
	//   listKey:
	//     - item

	type parseState int
	const (
		stateTop parseState = iota
		stateStyle
		stateList
	)

	state := stateTop
	currentStyleKey := ""
	currentStyle := &Style{}
	var currentList []string

	commitStyle := func() {
		if currentStyleKey == "" {
			return
		}
		switch currentStyleKey {
		case "buildStyle":
			config.BuildStyle = *currentStyle
		case "startStyle":
			config.StartStyle = *currentStyle
		case "passStyle":
			config.PassStyle = *currentStyle
		case "failStyle":
			config.FailStyle = *currentStyle
		case "skipStyle":
			config.SkipStyle = *currentStyle
		case "fileStyle":
			config.FileStyle = *currentStyle
		case "lineStyle":
			config.LineStyle = *currentStyle
		case "passPackageStyle":
			config.PassPackageStyle = *currentStyle
		case "failPackageStyle":
			config.FailPackageStyle = *currentStyle
		case "coveredStyle":
			config.CoveredStyle = *currentStyle
		case "uncoveredStyle":
			config.UncoveredStyle = *currentStyle
		}
		currentStyleKey = ""
		currentStyle = &Style{}
	}

	commitList := func() {
		if currentStyleKey != "" {
			switch currentStyleKey {
			case "removals":
				config.Removals = currentList
			}
		}
		currentStyleKey = ""
		currentList = nil
	}

	scanner := bufio.NewScanner(strings.NewReader(string(data)))
	_ = lines

	for scanner.Scan() {
		line := scanner.Text()

		// Skip comment lines
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "#") || trimmed == "" {
			continue
		}

		// Determine indentation level
		indent := len(line) - len(strings.TrimLeft(line, " \t"))

		if indent == 0 {
			// Top-level key
			if state == stateStyle {
				commitStyle()
			} else if state == stateList {
				commitList()
			}
			state = stateTop

			// Parse "key: value" or "key:"
			if colon := strings.Index(trimmed, ":"); colon >= 0 {
				key := strings.TrimSpace(trimmed[:colon])
				value := strings.TrimSpace(trimmed[colon+1:])

				if value == "" {
					// Could be start of a block
					switch key {
					case "buildStyle", "startStyle", "passStyle", "failStyle",
						"skipStyle", "fileStyle", "lineStyle", "passPackageStyle",
						"failPackageStyle", "coveredStyle", "uncoveredStyle":
						currentStyleKey = key
						currentStyle = &Style{}
						state = stateStyle
					case "removals":
						currentStyleKey = key
						currentList = nil
						state = stateList
					}
					continue
				}

				// Parse top-level key-value
				switch key {
				case "labelType":
					config.LabelType = unquote(value)
				case "coverThreshold":
					if f, err := strconv.ParseFloat(value, 64); err == nil {
						config.CoverThreshold = f
					}
				case "leaveTestPrefix":
					config.LeaveTestPrefix = parseBool(value)
				}
			}
		} else {
			// Indented line
			if state == stateStyle && indent > 0 {
				// Style sub-key
				if colon := strings.Index(trimmed, ":"); colon >= 0 {
					key := strings.TrimSpace(trimmed[:colon])
					value := strings.TrimSpace(trimmed[colon+1:])

					switch key {
					case "hide":
						currentStyle.Hide = parseBool(value)
					case "bold":
						currentStyle.Bold = parseBool(value)
					case "faint":
						currentStyle.Faint = parseBool(value)
					case "italic":
						currentStyle.Italic = parseBool(value)
					case "underline":
						currentStyle.Underline = parseBool(value)
					case "blinkSlow":
						currentStyle.BlinkSlow = parseBool(value)
					case "blinkRapid":
						currentStyle.BlinkRapid = parseBool(value)
					case "inverse":
						currentStyle.Inverse = parseBool(value)
					case "conceal":
						currentStyle.Conceal = parseBool(value)
					case "crossOut":
						currentStyle.CrossOut = parseBool(value)
					case "frame":
						currentStyle.Frame = parseBool(value)
					case "encircle":
						currentStyle.Encircle = parseBool(value)
					case "overline":
						currentStyle.Overline = parseBool(value)
					case "foreground":
						currentStyle.Foreground = unquote(value)
					case "background":
						currentStyle.Background = unquote(value)
					}
				}
			} else if state == stateList && indent > 0 {
				// List item
				if strings.HasPrefix(trimmed, "- ") {
					item := strings.TrimPrefix(trimmed, "- ")
					currentList = append(currentList, unquote(item))
				} else if strings.HasPrefix(trimmed, "-") {
					item := strings.TrimPrefix(trimmed, "-")
					currentList = append(currentList, unquote(strings.TrimSpace(item)))
				}
			}
		}
	}

	// Commit any pending state
	if state == stateStyle {
		commitStyle()
	} else if state == stateList {
		commitList()
	}
}

func parseBool(s string) bool {
	s = strings.ToLower(strings.TrimSpace(s))
	return s == "true" || s == "yes" || s == "1"
}

func unquote(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') ||
			(s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}
