// label returns the label prefix for a given kind and labelType
func (c *Config) label(kind string) string {
	switch c.LabelType {
	case "short":
		switch kind {
		case "build":
			return "!! "
		case "start":
			return ">  "
		case "pass":
			return "o  "
		case "fail":
			return "x  "
		case "skip":
			return "-  "
		case "cover":
			return "%  "
		case "cont":
			return "   "
		}
	case "none":
		return ""
	default: // "long"
		switch kind {
		case "build":
			return "BUILD| "
		case "start":
			return "START| "
		case "pass":
			return "PASS | "
		case "fail":
			return "FAIL | "
		case "skip":
			return "SKIP | "
		case "cover":
			return "COVER| "
		case "cont":
			return "     | "
		}
	}
	return ""
}

// Regexes for parsing
var (
	reRun      = regexp.MustCompile(`^=== RUN   (Test.*)$`)
	rePass     = regexp.MustCompile(`^--- PASS: (Test\S+)(.*)$`)
	reFail     = regexp.MustCompile(`^--- FAIL: (Test\S+)(.*)$`)
	reSkip     = regexp.MustCompile(`^--- SKIP: (Test\S+)(.*)$`)
	reBuild    = regexp.MustCompile(`^# (.+)$`)
	reCoverage = regexp.MustCompile(`^coverage: (\d+\.?\d*)% of statements$`)
	// ok  \tPKG\tTIME[\tcoverage: X% of statements]
	reOkPkg = regexp.MustCompile(`^ok  \t([^\t]+)\t[^\t]+(?:\t(coverage: .+))?$`)
	// FAIL\t... or standalone FAIL
	reFailPkg  = regexp.MustCompile(`^FAIL(\t.*)?$`)
	reSkipPkg  = regexp.MustCompile(`^\?   \t([^\t]*)\t(.*)$`)
	// file reference: indent + filename.go + :line[:col] + message
	reFileRef  = regexp.MustCompile(`^(\s*)(\S+\.go)(:\d+(?::\d+)?)(.*)$`)
)

// applyRemovals applies the removal regexps to a string
func (c *Config) applyRemovals(s string) string {
	for _, pattern := range c.Removals {
		re, err := regexp.Compile(pattern)
		if err == nil {
			s = re.ReplaceAllString(s, "")
		}
	}
	return s
}

// formatTestContent formats the test content (strips "Test" prefix if needed)
// Returns: (displayContent, depth)
// displayContent: the content to display after the label
// depth: number of '/' in the test name (for indentation)
func (c *Config) formatTestContent(content string) (string, int) {
	// Find the test name (first non-space chars)
	// For "=== RUN", content is the whole test name
	// For "--- PASS/FAIL/SKIP", content is "TestName rest"

	// Split at first whitespace to get the test name
	parts := strings.SplitN(content, " ", 2)
	testName := parts[0]
	rest := ""
	if len(parts) > 1 {
		rest = " " + parts[1]
	}

	depth := strings.Count(testName, "/")
	indent := strings.Repeat(" ", depth*2)

	displayName := testName
	if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
		displayName = testName[4:]
	}

	return indent + displayName + rest, depth
}

// formatTestName for "=== RUN" lines (no trailing content)
func (c *Config) formatRunName(testName string) (string, int) {
	depth := strings.Count(testName, "/")
	indent := strings.Repeat(" ", depth*2)

	displayName := testName
	if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
		displayName = testName[4:]
	}

	return indent + displayName, depth
}

// coverBar generates a coverage bar like "[####______]"
func coverBar(coverage float64) string {
	filled := int(math.Floor(coverage / 10))
	if filled > 10 {
		filled = 10
	}
	bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
	return "[" + bar + "]"
}

// Processor handles the test output filtering
type Processor struct {
	config       Config
	useColor     bool
	currentStyle *Style // current context style for continuation lines
}

// printLine prints a styled line with optional reset
func (p *Processor) printLine(w io.Writer, style Style, text string) {
	code := ansiCode(style)
	fmt.Fprintf(w, "%s%s%s\n", code, text, ansiReset)
}

// printFileRef prints a file reference line with special coloring
func (p *Processor) printFileRef(w io.Writer, contextStyle Style, label, origLine string) {
	code := ansiCode(contextStyle)
	fileCode := ansiCode(p.config.FileStyle)
	lineCode := ansiCode(p.config.LineStyle)

	// Apply removals to the line
	line := p.config.applyRemovals(origLine)

	m := reFileRef.FindStringSubmatch(line)
	if m != nil {
		indent := m[1]
		file := m[2]
		linecol := m[3]
		message := m[4]

		fmt.Fprintf(w, "%s%s%s%s%s%s%s%s%s%s\n",
			code, label, indent,
			fileCode, file, ansiReset,
			lineCode, linecol, ansiReset,
			code+message+ansiReset)
	} else {
		fmt.Fprintf(w, "%s%s%s%s\n", code, label, line, ansiReset)
	}
}

func (p *Processor) process(r io.Reader, w io.Writer) {
	if !p.useColor {
		// Pass through as-is
		io.Copy(w, r)
		fmt.Fprintln(w)
		fmt.Fprintln(w)
		return
	}

	scanner := bufio.NewScanner(r)
	c := &p.config
	var currentStyle *Style

	for scanner.Scan() {
		line := scanner.Text()

		// Try to match line patterns
		if m := reRun.FindStringSubmatch(line); m != nil {
			// START line
			testName := m[1]
			displayContent, _ := c.formatRunName(testName)
			label := c.label("start")
			currentStyle = &c.StartStyle
			if c.StartStyle.Hide {
				currentStyle = nil
				continue
			}
			p.printLine(w, c.StartStyle, label+displayContent)
			continue
		}

		if m := rePass.FindStringSubmatch(line); m != nil {
			// PASS line
			if c.PassStyle.Hide {
				currentStyle = nil
				continue
			}
			testName := m[1]
			rest := m[2] // already includes leading space (e.g., " (0.00s)")
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			content := c.applyRemovals(indent + displayName + rest)
			label := c.label("pass")
			currentStyle = &c.PassStyle
			p.printLine(w, c.PassStyle, label+content)
			continue
		}

		if m := reFail.FindStringSubmatch(line); m != nil {
			// FAIL line
			if c.FailStyle.Hide {
				currentStyle = nil
				continue
			}
			testName := m[1]
			rest := m[2]
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			content := c.applyRemovals(indent + displayName + rest)
			label := c.label("fail")
			currentStyle = &c.FailStyle
			p.printLine(w, c.FailStyle, label+content)
			continue
		}

		if m := reSkip.FindStringSubmatch(line); m != nil {
			// SKIP line
			if c.SkipStyle.Hide {
				currentStyle = nil
				continue
			}
			testName := m[1]
			rest := m[2]
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			content := c.applyRemovals(indent + displayName + rest)
			label := c.label("skip")
			currentStyle = &c.SkipStyle
			p.printLine(w, c.SkipStyle, label+content)
			continue
		}

		if m := reBuild.FindStringSubmatch(line); m != nil {
			// BUILD line (start of build block)
			pkgName := m[1]
			if c.BuildStyle.Hide {
				currentStyle = nil
				continue
			}
			label := c.label("build")
			code := ansiCode(c.BuildStyle)
			// BUILD first line has \n BEFORE reset
			fmt.Fprintf(w, "%s%s%s\n%s", code, label, pkgName, ansiReset)
			currentStyle = &c.BuildStyle
			continue
		}

		if m := reCoverage.FindStringSubmatch(line); m != nil {
			// COVER line (standalone)
			currentStyle = nil
			covStr := m[1]
			cov, err := strconv.ParseFloat(covStr, 64)
			var coverStyle Style
			if err == nil && cov >= c.CoverThreshold {
				coverStyle = c.CoveredStyle
			} else {
				coverStyle = c.UncoveredStyle
			}
			if coverStyle.Hide {
				continue
			}
			bar := coverBar(cov)
			label := c.label("cover")
			p.printLine(w, coverStyle, fmt.Sprintf("%s%s%% %s", label, covStr, bar))
			continue
		}

		if m := reOkPkg.FindStringSubmatch(line); m != nil {
			// Pass package line (ok)
			currentStyle = nil
			pkg := m[1]
			coverage := m[2]
			label := c.label("pass")
			content := pkg + " "
			if coverage != "" {
				content = pkg + " " + coverage
			}
			p.printLine(w, c.PassPackageStyle, label+content)
			continue
		}

		if line == "PASS" {
			// Standalone PASS (package result)
			currentStyle = nil
			if c.PassPackageStyle.Hide {
				continue
			}
			code := ansiCode(c.PassPackageStyle)
			fmt.Fprintf(w, "%sPASS%s\n", code, ansiReset)
			continue
		}

		if m := reFailPkg.FindStringSubmatch(line); m != nil {
			// FAIL package line or standalone FAIL
			currentStyle = nil
			rest := m[1] // "\tpkg\ttime" or ""
			if rest == "" {
				// Standalone FAIL
				if c.FailPackageStyle.Hide {
					continue
				}
				code := ansiCode(c.FailPackageStyle)
				fmt.Fprintf(w, "%sFAIL%s\n", code, ansiReset)
			} else {
				// FAIL\tpkg\ttime
				label := c.label("fail")
				code := ansiCode(c.FailPackageStyle)
				fmt.Fprintf(w, "%s%s%s%s\n", code, label, rest, ansiReset)
			}
			continue
		}

		if m := reSkipPkg.FindStringSubmatch(line); m != nil {
			// Skip package line (? pkg [no test files])
			currentStyle = nil
			if c.SkipStyle.Hide {
				continue
			}
			pkg := m[1]
			info := m[2]
			label := c.label("skip")
			content := pkg + "\t" + info
			p.printLine(w, c.SkipStyle, label+content)
			continue
		}

		// Unknown/continuation line
		if currentStyle != nil {
			// We're in a context (build, fail, pass, skip, start)
			label := c.label("cont")
			p.printFileRef(w, *currentStyle, label, line)
		} else {
			// No current style context
			label := c.label("cont")
			line = c.applyRemovals(line)
			fmt.Fprintf(w, "%s%s\n", label, line)
		}
	}
}

type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func isatty(fd uintptr) bool {
	var ws Winsize
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	return err == 0
}

func isColorEnabled() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	return isatty(os.Stdout.Fd())
}

func runTestFilter(r io.Reader, w io.Writer) {
	config := loadConfig()
	useColor := isColorEnabled()

	proc := &Processor{
		config:   config,
		useColor: useColor,
	}
	proc.process(r, w)
}

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		// No subcommand - run "go" with no args
		cmd := exec.Command("go")
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		return
	}

	if args[0] == "testfilter" {
		runTestFilter(os.Stdin, os.Stdout)
		return
	}

	if args[0] == "test" {
		// Run "go test" and pipe through testfilter
		goArgs := append([]string{"test"}, args[1:]...)
		cmd := exec.Command("go", goArgs...)

		useColor := isColorEnabled()

		if useColor {
			pr, pw, err := os.Pipe()
			if err != nil {
				cmd.Stdout = os.Stdout
				cmd.Stderr = os.Stderr
				cmd.Stdin = os.Stdin
				cmd.Run()
				return
			}
			cmd.Stdout = pw
			cmd.Stderr = pw
			cmd.Stdin = os.Stdin

			done := make(chan struct{})
			go func() {
				defer close(done)
				runTestFilter(pr, os.Stdout)
			}()

			cmd.Run()
			pw.Close()
			<-done
		} else {
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			cmd.Stdin = os.Stdin
			cmd.Run()
		}
		return
	}

	// Pass through to "go"
	cmd := exec.Command("go", args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}
