		}
	}
	return ""
}

// Regexes for parsing test output lines
var (
	reRun     = regexp.MustCompile(`^=== RUN   (Test.*)$`)
	rePass    = regexp.MustCompile(`^--- PASS: (Test\S+)(.*)$`)
	reFail    = regexp.MustCompile(`^--- FAIL: (Test\S+)(.*)$`)
	reSkip    = regexp.MustCompile(`^--- SKIP: (Test\S+)(.*)$`)
	reBuild   = regexp.MustCompile(`^# (.+)$`)
	reCoverage = regexp.MustCompile(`^coverage: (\d+\.?\d*)% of statements$`)
	// "ok  \tPKG\tTIME" optionally followed by "\tcoverage: ..."
	reOkPkg   = regexp.MustCompile(`^ok  \t([^\t]+)\t[^\t]+(?:\t(coverage: .+))?$`)
	// "FAIL" followed by optional "\t..." or nothing
	reFailPkg = regexp.MustCompile(`^FAIL(\t.*)?$`)
	// "?   \tPKG\t[info]"
	reSkipPkg = regexp.MustCompile(`^\?   \t([^\t]*)\t(.*)$`)
	// file reference line: optional_spaces + file.go + :line[:col] + rest
	reFileRef = regexp.MustCompile(`^(\s*)(\S+\.go)(:\d+(?::\d+)?)(.*)$`)
)

// applyRemovals applies the removal regexps to a string
func (c *Config) applyRemovals(s string) string {
	for _, pattern := range c.Removals {
		re, err := regexp.Compile(pattern)
		if err == nil {
			s = re.ReplaceAllString(s, "")
		}
	}
	return s
}

// coverBar generates a progress bar like "[####______]" for coverage percentage
func coverBar(coverage float64) string {
	filled := int(math.Floor(coverage / 10))
	if filled > 10 {
		filled = 10
	}
	bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
	return "[" + bar + "]"
}

// Processor handles the test output filtering and transformation
type Processor struct {
	config       Config
	useColor     bool
	currentStyle *Style // current context style for continuation lines
}

// printLine writes a styled line with reset at the end
func (p *Processor) printLine(w io.Writer, style Style, text string) {
	code := ansiCode(style)
	fmt.Fprintf(w, "%s%s%s\n", code, text, ansiReset)
}

// printFileRef writes a file reference line with special coloring for filename and line numbers
func (p *Processor) printFileRef(w io.Writer, contextStyle Style, label, origLine string) {
	code := ansiCode(contextStyle)
	fileCode := ansiCode(p.config.FileStyle)
	lineCode := ansiCode(p.config.LineStyle)

	// Apply removals to the line
	line := p.config.applyRemovals(origLine)

	m := reFileRef.FindStringSubmatch(line)
	if m != nil {
		indent := m[1]
		file := m[2]
		linecol := m[3]
		message := m[4]

		fmt.Fprintf(w, "%s%s%s%s%s%s%s%s%s%s\n",
			code, label, indent,
			fileCode, file, ansiReset,
			lineCode, linecol, ansiReset,
			code+message+ansiReset)
	} else {
		fmt.Fprintf(w, "%s%s%s%s\n", code, label, line, ansiReset)
	}
}

func (p *Processor) process(r io.Reader, w io.Writer) {
	if !p.useColor {
		// Pass through as-is with 2 trailing newlines
		io.Copy(w, r)
		fmt.Fprintln(w)
		fmt.Fprintln(w)
		return
	}

	scanner := bufio.NewScanner(r)
	c := &p.config
	var currentStyle *Style

	for scanner.Scan() {
		line := scanner.Text()

		// Match "=== RUN   TestXxx"
		if m := reRun.FindStringSubmatch(line); m != nil {
			testName := m[1]
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			label := c.label("start")
			currentStyle = &c.StartStyle
			if c.StartStyle.Hide {
				currentStyle = nil
				continue
			}
			p.printLine(w, c.StartStyle, label+indent+displayName)
			continue
		}

		// Match "--- PASS: TestXxx ..."
		if m := rePass.FindStringSubmatch(line); m != nil {
			if c.PassStyle.Hide {
				currentStyle = nil
				continue
			}
			testName := m[1]
			rest := m[2] // includes leading space if any (e.g., " (0.00s)")
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			content := c.applyRemovals(indent + displayName + rest)
			label := c.label("pass")
			currentStyle = &c.PassStyle
			p.printLine(w, c.PassStyle, label+content)
			continue
		}

		// Match "--- FAIL: TestXxx ..."
		if m := reFail.FindStringSubmatch(line); m != nil {
			if c.FailStyle.Hide {
				currentStyle = nil
				continue
			}
			testName := m[1]
			rest := m[2]
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			content := c.applyRemovals(indent + displayName + rest)
			label := c.label("fail")
			currentStyle = &c.FailStyle
			p.printLine(w, c.FailStyle, label+content)
			continue
		}

		// Match "--- SKIP: TestXxx ..."
		if m := reSkip.FindStringSubmatch(line); m != nil {
			if c.SkipStyle.Hide {
				currentStyle = nil
				continue
			}
			testName := m[1]
			rest := m[2]
			depth := strings.Count(testName, "/")
			indent := strings.Repeat(" ", depth*2)
			displayName := testName
			if !c.LeaveTestPrefix && strings.HasPrefix(testName, "Test") {
				displayName = testName[4:]
			}
			content := c.applyRemovals(indent + displayName + rest)
			label := c.label("skip")
			currentStyle = &c.SkipStyle
			p.printLine(w, c.SkipStyle, label+content)
			continue
		}

		// Match "# pkg" build header
		if m := reBuild.FindStringSubmatch(line); m != nil {
			pkgName := m[1]
			if c.BuildStyle.Hide {
				currentStyle = nil
				continue
			}
			label := c.label("build")
			code := ansiCode(c.BuildStyle)
			// BUILD first line: style + label + pkg + \n + reset (newline BEFORE reset)
			fmt.Fprintf(w, "%s%s%s\n%s", code, label, pkgName, ansiReset)
			currentStyle = &c.BuildStyle
			continue
		}

		// Match "coverage: X.X% of statements"
		if m := reCoverage.FindStringSubmatch(line); m != nil {
			currentStyle = nil
			covStr := m[1]
			cov, err := strconv.ParseFloat(covStr, 64)
			var coverStyle Style
			if err == nil && cov >= c.CoverThreshold {
				coverStyle = c.CoveredStyle
			} else {
				coverStyle = c.UncoveredStyle
			}
			if coverStyle.Hide {
				continue
			}
			bar := coverBar(cov)
			label := c.label("cover")
			p.printLine(w, coverStyle, fmt.Sprintf("%s%s%% %s", label, covStr, bar))
			continue
		}

