		if m := reFailPkg.FindStringSubmatch(line); m != nil {
			currentStyle = nil
			rest := m[1] // "\tpkg\ttime" or "" (nil if no capture)
			if rest == "" {
				// Standalone FAIL
				if c.FailPackageStyle.Hide {
					continue
				}
				code := ansiCode(c.FailPackageStyle)
				fmt.Fprintf(w, "%sFAIL%s\n", code, ansiReset)
			} else {
				// FAIL\tpkg\ttime
				label := c.label("fail")
				code := ansiCode(c.FailPackageStyle)
				fmt.Fprintf(w, "%s%s%s%s\n", code, label, rest, ansiReset)
			}
			continue
		}

		// Match "?   \tPKG\t[info]"
		if m := reSkipPkg.FindStringSubmatch(line); m != nil {
			currentStyle = nil
			if c.SkipStyle.Hide {
				continue
			}
			pkg := m[1]
			info := m[2]
			label := c.label("skip")
			content := pkg + "\t" + info
			p.printLine(w, c.SkipStyle, label+content)
			continue
		}

		// Unknown/continuation line
		if currentStyle != nil {
			// In a styled context (build, pass, fail, skip, start)
			label := c.label("cont")
			p.printFileRef(w, *currentStyle, label, line)
		} else {
			// No current style context - just use continuation label without color
			label := c.label("cont")
			processedLine := c.applyRemovals(line)
			fmt.Fprintf(w, "%s%s\n", label, processedLine)
		}
	}
}

// Winsize structure for terminal size ioctl
type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

// isatty checks if a file descriptor is a terminal
func isatty(fd uintptr) bool {
	var ws Winsize
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	return err == 0
}

// isColorEnabled returns true if color output should be used
func isColorEnabled() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	return isatty(os.Stdout.Fd())
}

// runTestFilter reads from r, processes it, and writes to w
func runTestFilter(r io.Reader, w io.Writer) {
	config := loadConfig()
	useColor := isColorEnabled()

	proc := &Processor{
		config:   config,
		useColor: useColor,
	}
	proc.process(r, w)
}

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		// No subcommand - run "go" with no args to show usage
		cmd := exec.Command("go")
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		return
	}

	if args[0] == "testfilter" {
		runTestFilter(os.Stdin, os.Stdout)
		return
	}

	if args[0] == "test" {
		// Run "go test ..." with rich output
		goArgs := append([]string{"test"}, args[1:]...)
		cmd := exec.Command("go", goArgs...)

		useColor := isColorEnabled()

		if useColor {
			// Pipe go test output through our filter
			pr, pw, err := os.Pipe()
			if err != nil {
				cmd.Stdout = os.Stdout
				cmd.Stderr = os.Stderr
				cmd.Stdin = os.Stdin
				cmd.Run()
				return
			}
			cmd.Stdout = pw
			cmd.Stderr = pw
			cmd.Stdin = os.Stdin

			done := make(chan struct{})
			go func() {
				defer close(done)
				runTestFilter(pr, os.Stdout)
			}()

			cmd.Run()
			pw.Close()
			<-done
		} else {
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			cmd.Stdin = os.Stdin
			cmd.Run()
		}
		return
	}

	// Pass all other commands through to "go"
	cmd := exec.Command("go", args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}
