		if m := reSkipPkg.FindStringSubmatch(line); m != nil {
			currentStyle = nil
			if c.SkipStyle.Hide {
				continue
			}
			pkg := m[1]
			info := m[2]
			label := c.label("skip")
			content := pkg + "\t" + info
			p.printLine(w, c.SkipStyle, label+content)
			continue
		}

