}

// runTestFilter reads from r, processes it, and writes to w
func runTestFilter(r io.Reader, w io.Writer) {
	config := loadConfig()
	useColor := isColorEnabled()

	proc := &Processor{
		config:   config,
		useColor: useColor,
	}
