func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		// No subcommand - run "go" with no args to show usage
		cmd := exec.Command("go")
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
