			// Pipe go test output through our filter
			pr, pw, err := os.Pipe()
			if err != nil {
				cmd.Stdout = os.Stdout
				cmd.Stderr = os.Stderr
				cmd.Stdin = os.Stdin
				cmd.Run()
				return
			}
			cmd.Stdout = pw
			cmd.Stderr = pw
