			filepath.Join(home, ".richstyle"),
			filepath.Join(home, ".richstyle.yaml"),
			filepath.Join(home, ".richstyle.yml"),
		)
	}

	return paths
}

// getGoRoot tries to get GOROOT by running "go env GOROOT"
func getGoRoot() string {
	out, err := exec.Command("go", "env", "GOROOT").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// parseConfig parses a YAML config file and updates the config
func parseConfig(data []byte, config *Config) {
	type parseState int
	const (
		stateTop parseState = iota
		stateStyle
		stateList
	)

	state := stateTop
	currentStyleKey := ""
	currentStyle := &Style{}
	var currentList []string

	commitStyle := func() {
		if currentStyleKey == "" {
			return
		}
		switch currentStyleKey {
		case "buildStyle":
			config.BuildStyle = *currentStyle
		case "startStyle":
			config.StartStyle = *currentStyle
		case "passStyle":
			config.PassStyle = *currentStyle
		case "failStyle":
			config.FailStyle = *currentStyle
		case "skipStyle":
			config.SkipStyle = *currentStyle
		case "fileStyle":
			config.FileStyle = *currentStyle
		case "lineStyle":
			config.LineStyle = *currentStyle
		case "passPackageStyle":
			config.PassPackageStyle = *currentStyle
		case "failPackageStyle":
			config.FailPackageStyle = *currentStyle
		case "coveredStyle":
			config.CoveredStyle = *currentStyle
		case "uncoveredStyle":
			config.UncoveredStyle = *currentStyle
		}
		currentStyleKey = ""
		currentStyle = &Style{}
	}

	commitList := func() {
		if currentStyleKey != "" {
			switch currentStyleKey {
			case "removals":
				config.Removals = currentList
			}
		}
		currentStyleKey = ""
		currentList = nil
	}

	scanner := bufio.NewScanner(strings.NewReader(string(data)))

	for scanner.Scan() {
		line := scanner.Text()

		// Skip comment lines and empty lines
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "#") || trimmed == "" {
			continue
		}

		// Determine indentation level
		indent := len(line) - len(strings.TrimLeft(line, " \t"))

		if indent == 0 {
			// Top-level key - commit any pending state first
			if state == stateStyle {
				commitStyle()
			} else if state == stateList {
				commitList()
			}
			state = stateTop

			// Parse "key: value" or "key:" (block start)
			if colon := strings.Index(trimmed, ":"); colon >= 0 {
				key := strings.TrimSpace(trimmed[:colon])
				value := strings.TrimSpace(trimmed[colon+1:])

				if value == "" {
					// Start of a block
					switch key {
					case "buildStyle", "startStyle", "passStyle", "failStyle",
						"skipStyle", "fileStyle", "lineStyle", "passPackageStyle",
						"failPackageStyle", "coveredStyle", "uncoveredStyle":
						currentStyleKey = key
						currentStyle = &Style{}
						state = stateStyle
					case "removals":
						currentStyleKey = key
						currentList = nil
						state = stateList
					}
					continue
				}

				// Top-level key-value
				switch key {
				case "labelType":
					config.LabelType = unquote(value)
				case "coverThreshold":
					if f, err := strconv.ParseFloat(value, 64); err == nil {
						config.CoverThreshold = f
					}
				case "leaveTestPrefix":
					config.LeaveTestPrefix = parseBool(value)
				}
			}
		} else {
			// Indented line - must be inside a style block or list
			if state == stateStyle {
				// Parse style sub-key: value
				if colon := strings.Index(trimmed, ":"); colon >= 0 {
					key := strings.TrimSpace(trimmed[:colon])
					value := strings.TrimSpace(trimmed[colon+1:])

					switch key {
					case "hide":
						currentStyle.Hide = parseBool(value)
					case "bold":
						currentStyle.Bold = parseBool(value)
					case "faint":
						currentStyle.Faint = parseBool(value)
					case "italic":
						currentStyle.Italic = parseBool(value)
					case "underline":
						currentStyle.Underline = parseBool(value)
					case "blinkSlow":
						currentStyle.BlinkSlow = parseBool(value)
					case "blinkRapid":
						currentStyle.BlinkRapid = parseBool(value)
					case "inverse":
						currentStyle.Inverse = parseBool(value)
					case "conceal":
						currentStyle.Conceal = parseBool(value)
					case "crossOut":
						currentStyle.CrossOut = parseBool(value)
					case "frame":
						currentStyle.Frame = parseBool(value)
					case "encircle":
						currentStyle.Encircle = parseBool(value)
					case "overline":
						currentStyle.Overline = parseBool(value)
					case "foreground":
						currentStyle.Foreground = unquote(value)
					case "background":
						currentStyle.Background = unquote(value)
					}
				}
			} else if state == stateList {
				// Parse list item: "- item"
				if strings.HasPrefix(trimmed, "- ") {
					item := strings.TrimPrefix(trimmed, "- ")
					currentList = append(currentList, unquote(item))
				} else if trimmed == "-" {
					// Empty item
					currentList = append(currentList, "")
				}
			}
		}
	}

	// Commit any pending state at end of file
	if state == stateStyle {
		commitStyle()
	} else if state == stateList {
		commitList()
	}
}

func parseBool(s string) bool {
	s = strings.ToLower(strings.TrimSpace(s))
	return s == "true" || s == "yes" || s == "1"
}

func unquote(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') ||
			(s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}
